@RunWith(PowerMockRunner.class)
@PrepareForTest({CommandLineRunner.class, System.class})
public class CommandLineRunner_main_TriageGen1Test {

    /**
     * Test case for the branch where shouldRunCompiler returns true.
     * This covers the 'if' block.
     */
    @Test
    public void testMain_shouldRunCompilerTrue() throws Exception {
        String[] args = {"--some-flag"};

        // Mock CommandLineRunner to control shouldRunCompiler and run
        CommandLineRunner mockRunner = mock(CommandLineRunner.class);
        when(mockRunner.shouldRunCompiler()).thenReturn(true);
        doNothing().when(mockRunner).run();

        // Use PowerMock to intercept the constructor call 'new CommandLineRunner(args)'
        PowerMockito.whenNew(CommandLineRunner.class)
                    .withArguments(args)
                    .thenReturn(mockRunner);

        // Execute the main method
        CommandLineRunner.main(args);

        // Verify interactions
        verify(mockRunner, times(1)).shouldRunCompiler();
        verify(mockRunner, times(1)).run();
        // Verify System.exit was NOT called
        PowerMockito.verifyStatic(System.class, never());
        System.exit(anyInt());
    }

    /**
     * Test case for the branch where shouldRunCompiler returns false.
     * This covers the 'else' block and the System.exit(-1) call.
     */
    @Test
    public void testMain_shouldRunCompilerFalse() throws Exception {
        String[] args = {"--some-flag"};

        CommandLineRunner mockRunner = mock(CommandLineRunner.class);
        when(mockRunner.shouldRunCompiler()).thenReturn(false);

        PowerMockito.whenNew(CommandLineRunner.class)
                    .withArguments(args)
                    .thenReturn(mockRunner);

        // Mock System.exit to prevent the JVM from actually shutting down during tests
        PowerMockito.mockStatic(System.class);

        // Execute the main method
        CommandLineRunner.main(args);

        // Verify interactions
        verify(mockRunner, times(1)).shouldRunCompiler();
        verify(mockRunner, never()).run();

        // Verify System.exit(-1) was called
        PowerMockito.verifyStatic(System.class);
        System.exit(-1);
    }
}
